"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["35451"],{10544(e){e.exports=JSON.parse('{"id":"F338","slug":"asian-option-payoff","name":"Asian Option Payoff","subject":"Derivatives","section":"Derivatives","topic":"Exotic options","level":"Intermediate","aliases":["average price option","exotic options","path dependent option"],"formula":{"latex":"\\\\text{Payoff}=\\\\max(\\\\bar{S}-K,0),\\\\quad \\\\bar{S}=\\\\frac{1}{n}\\\\sum S_{i}","also":[],"text":"Asian call payoff = max(Average price over the period - Strike, 0); the average of the prices recorded on set dates"},"symbols":[{"symbol":"S-bar","meaning":"Average of the underlying prices on the observation dates","unit":"money"},{"symbol":"K","meaning":"Strike price","unit":"money"},{"symbol":"n","meaning":"Number of observation dates","unit":"number"}],"when_to_use":"Use it to see the payoff of an option on the average price. Averaging smooths out price spikes, so the option has lower volatility and is cheaper than a standard option. It is popular with commodity buyers who purchase evenly through the year.","worked_example":{"problem":"Month-end prices of an asset are 100, 104, 98, 106, 110 and 108. A call has a strike of 100. What do an average-price (Asian) call and an ordinary call pay?","inputs":{"p":[100,104,98,106,110,108],"k":100},"steps":[{"label":"Average price","working":null,"value":"104.33"},{"label":"Asian call payoff = max(average - K, 0)","working":"max(104.333-100, 0)","value":"4.33"},{"label":"Ordinary call payoff = max(last price - K, 0)","working":"max([100, 104, 98, 106, 110, 108][-1]-100, 0)","value":"8.00"}],"answer":"The average price is 104.33, so the Asian call pays 4.33. The ordinary call, based on the final price of 108, pays 8.00. Averaging lowered the payoff here because the price rose through the period."},"calculator":{"available":true,"inputs":[{"id":"p","label":"Prices on the observation dates","unit":"money","type":"list","default":[100,104,98,106,110,108],"hint":""},{"id":"k","label":"Strike price","unit":"money","type":"number","default":100,"hint":""}],"checks":[{"expr":"count(p)>=2","message":"Enter at least two prices."}],"steps":[{"id":"avg","label":"Average price","expr":"mean(p)","format":"money"},{"id":"asian","label":"Asian call payoff = max(average - K, 0)","expr":"max(avg-k, 0)","format":"money"},{"id":"euro","label":"Ordinary call payoff = max(last price - K, 0)","expr":"max(p[-1]-k, 0)","format":"money"}],"results":["asian","euro"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"avg":104.33333333333333,"asian":4.333333333333329,"euro":8}},"finder":{"finds":"What an average-price option pays","needs":"Observed prices, strike"},"related":[{"slug":"barrier-option-payoff","name":"Barrier Option Payoff"},{"slug":"option-payoffs","name":"Call and Put Payoffs and Profit"}],"related_ids":["F339","F325"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Payoff</mtext><mo>=</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mover accent=\\"true\\"><mi>S</mi><mo>\u02C9</mo></mover><mo>\u2212</mo><mi>K</mi><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mover accent=\\"true\\"><mi>S</mi><mo>\u02C9</mo></mover><mo>=</mo><mfrac><mn>1</mn><mi>n</mi></mfrac><mo>\u2211</mo><msub><mi>S</mi><mi>i</mi></msub></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Payoff}=\\\\max(\\\\bar{S}-K,0),\\\\quad \\\\bar{S}=\\\\frac{1}{n}\\\\sum S_{i}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"arithmetic-mean-return","name":"Arithmetic Mean Return"},"next":{"slug":"asset-manager-economics","name":"Asset Manager Revenue and Fee Sensitivity"},"lesson":null,"total":522}')}}]);